37|import * as echarts from 'echarts'
38|
39|export default {
40|  name: 'Dashboard',
41|  data() {
42|    return {
43|      visitChart: null,
44|      pieChart: null
45|    }
46|  },
47|  mounted() {
48|    this.$nextTick(() => {
49|      this.initVisitChart()
50|      this.initPieChart()
51|    })
52|    window.addEventListener('resize', this.handleResize)
53|  },
54|  beforeDestroy() {
55|    window.removeEventListener('resize', this.handleResize)
56|    if (this.visitChart) {
57|      this.visitChart.dispose()
58|    }
59|    if (this.pieChart) {
60|      this.pieChart.dispose()
61|    }
62|  },
63|  methods: {
64|    initVisitChart() {
65|      const chartDom = this.$refs.visitChart
66|      if (!chartDom) return
67|      this.visitChart = echarts.init(chartDom)
68|      const option = {
69|        tooltip: {
70|          trigger: 'axis'
71|        },
72|        grid: {
73|          left: '3%',
74|          right: '4%',
75|          bottom: '3%',
76|          top: '10%',
77|          containLabel: true
78|        },
79|        xAxis: {
80|          type: 'category',
81|          boundaryGap: false,
82|          data: ['周一', '周二', '周三', '周四', '周五', '周六', '周日']
83|        },
84|        yAxis: {
85|          type: 'value'
86|        },
87|        series: [
88|          {
89|            name: '访问量',
90|            type: 'line',
91|            smooth: true,
92|            data: [120, 200, 150, 80, 70, 110, 130],
93|            itemStyle: {
94|              color: '#1890ff'
95|            },
96|            areaStyle: {
97|              color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
98|                { offset: 0, color: 'rgba(24, 144, 255, 0.6)' },
99|                { offset: 1, color: 'rgba(24, 144, 255, 0.1)' }
100|              ])
101|            }
102|          }
103|        ]
104|      }
105|      this.visitChart.setOption(option)
106|    },
107|    initPieChart() {
108|      const chartDom = this.$refs.pieChart
109|      if (!chartDom) return
110|      this.pieChart = echarts.init(chartDom)
111|      const option = {
112|        tooltip: {
113|          trigger: 'item'
114|        },
115|        legend: {
116|          top: '5%',
117|          left: 'center'
118|        },
119|        series: [
120|          {
121|            name: '功能使用',
122|            type: 'pie',
123|            radius: ['40%', '70%'],
124|            avoidLabelOverlap: false,
125|            itemStyle: {
126|              borderRadius: 10,
127|              borderColor: '#fff',
128|              borderWidth: 2
129|            },
130|            label: {
131|              show: false,
132|              position: 'center'
133|            },
134|            emphasis: {
135|              label: {
136|                show: true,
137|                fontSize: '16',
138|                fontWeight: 'bold'
139|              }
140|            },
141|            labelLine: {
142|              show: false
143|            },
144|            data: [
145|              { value: 335, name: '用户管理' },
146|              { value: 310, name: '订单管理' },
147|              { value: 234, name: '数据分析' },
148|              { value: 135, name: '系统设置' },
149|              { value: 154, name: '消息中心' }
150|            ],
151|            color: ['#1890ff', '#13c2c2', '#52c41a', '#faad14', '#f5222d']
152|          }
153|        ]
154|      }
155|      this.pieChart.setOption(option)
156|    },
157|    handleResize() {
158|      if (this.visitChart) {
159|        this.visitChart.resize()
160|      }
161|      if (this.pieChart) {
162|        this.pieChart.resize()
163|      }
164|    }
165|  }
166|}
167|</script>
